package com.yuegang.zhihui.product.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.product.security.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;import org.springframework.data.redis.core.StringRedisTemplate;
@Configuration(proxyBeanMethods=false)class ProductConfiguration{@Bean ProductService productService(DataSource d){return new ProductService(d);}@Bean ProductAdministrationService productAdministrationService(DataSource d,ProductService p,ObjectMapper j){return new ProductAdministrationService(d,p,j);}@Bean ProductCacheService productCacheService(StringRedisTemplate r,ObjectMapper j){return new ProductCacheService(r,j);}@Bean CatalogService catalogService(DataSource d,ObjectMapper j){return new CatalogService(d,j);}@Bean ProductAdminVerifier productAdminVerifier(@Value("${YGH_INTERNAL_REQUEST_HMAC_BASE64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new ProductAdminVerifier(k);}finally{Arrays.fill(k,(byte)0);}}}
